const nodeDefinitions = [
  {
    type: 'node.daemon.started',
    version: '1.0.0',
    validate: (payload) => {
      if (!payload?.nodeId) throw new Error('node.daemon.started requires nodeId')
    },
    partitionKey: (p) => `node#${p.nodeId}`,
  },
  {
    type: 'node.daemon.stopped',
    version: '1.0.0',
    validate: (payload) => {
      if (!payload?.nodeId) throw new Error('node.daemon.stopped requires nodeId')
    },
    partitionKey: (p) => `node#${p.nodeId}`,
  },
  {
    type: 'node.daemon.plugin.start.requested',
    version: '1.0.0',
    validate: (payload) => {
      if (!payload?.plugin) throw new Error('node.daemon.plugin.start.requested requires plugin')
    },
    partitionKey: (p) => `plugin#${p.plugin}`,
  },
  {
    type: 'node.daemon.plugin.started',
    version: '1.0.0',
    validate: (payload) => {
      if (!payload?.plugin) throw new Error('node.daemon.plugin.started requires plugin')
    },
    partitionKey: (p) => `plugin#${p.plugin}`,
  },
  {
    type: 'node.daemon.plugin.stop.requested',
    version: '1.0.0',
    validate: (payload) => {
      if (!payload?.plugin) throw new Error('node.daemon.plugin.stop.requested requires plugin')
    },
    partitionKey: (p) => `plugin#${p.plugin}`,
  },
  {
    type: 'node.daemon.plugin.stopped',
    version: '1.0.0',
    validate: (payload) => {
      if (!payload?.plugin) throw new Error('node.daemon.plugin.stopped requires plugin')
    },
    partitionKey: (p) => `plugin#${p.plugin}`,
  },
  {
    type: 'node.log.emitted',
    version: '1.0.0',
    persisted: false,
    replicated: false,
    validate: (payload) => {
      if (!payload?.message) throw new Error('node.log.emitted requires message')
    },
    partitionKey: (p) => `node#${p.nodeId || 'default'}`,
  },
]

module.exports = {
  nodeDefinitions,
}
